import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四十一章","description":"《正易心法》第四十一章——易道弥漫，九流可入：易本于阴阳，万物负阴而抱阳，故惟其所入；束于辞训则犯法，得悟则辞外见意、纵横妙用是为活法；当于羲皇心地上驰骋。","frontmatter":{"title":"正易心法·第四十一章","description":"《正易心法》第四十一章——易道弥漫，九流可入：易本于阴阳，万物负阴而抱阳，故惟其所入；束于辞训则犯法，得悟则辞外见意、纵横妙用是为活法；当于羲皇心地上驰骋。","category":"guide","aliases":["正易心法第四十一章","易道弥漫九流可入","活法与自悟"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-41.md","filePath":"yijing/zheng-yi-xin-fa/chapter-41.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-41.md"},x=p({...c,setup(u){const i=[{id:"z41-01",label:"一、易道弥漫",showLabel:!0,sentences:[["易道",{text:"弥漫",glossary:"miman"},"，",{text:"九流",glossary:"jiuliu"},"可入。当知",{text:"活法",glossary:"huofa"},"，要须",{text:"自悟",glossary:"ziwu"},"。"]],note:["《易》道充满一切，九流百家皆可从中入门；应当知道「活法」，关键在于自己领悟。（**本章是全书正文的最后一章，也是方法论的总收束**——前四十章教了那么多象数义理，最后这一章说的是：**这一切，都只是入门的路；真正的目的是自悟活法。**）"]},{id:"z41-02",label:"二、负阴而抱阳",showLabel:!0,sentences:[["《易》之为书，本于阴阳。万物负阴而抱阳，何适而非阴阳也？是以在人惟其所入耳。"]],note:["《易》这部书本于阴阳。万物负阴而抱阳，哪里不是阴阳呢？所以对人来说，只在于从哪个角度入门。（**「万物负阴而抱阳」出《老子》四十二章**。**「何适而非阴阳」是本章能成立的前提**：**任何学问、任何事物都在阴阳之中，所以任何领域都可以入《易》。**）"]},{id:"z41-03",label:"三、各以其道入",showLabel:!0,sentences:[["文王、周公以",{text:"庶类",glossary:"shulei"},"入，宣父以",{text:"八物",glossary:"bawu"},"入，斯其上也。其后或以",{text:"律度",glossary:"lüdu"},"入，或以",{text:"历数",glossary:"lishu"},"入，或以",{text:"仙道",glossary:"xiandao"},"入。以此知《易》道无往而不可也。"]],note:["文王、周公从万事万物的变化来入，孔子从八卦所象之物来入——这是最高的入法；此后有人从音律度量来入，有人从历法数术来入，有人从仙道修炼来入。由此可知，《易》道无处不可通达。（**两层的分辨**：**「庶类」是最宽广的入法**（从万类的共同规律入手），**「八物」是最精准的入法**（以具体的象把握抽象的理）；**律度、历数、仙道则是从某一专门领域切入**，各有所得而较窄。）"]},{id:"z41-04",label:"四、束于辞训",showLabel:!0,sentences:[["苟惟束于",{text:"辞训",glossary:"cixun"},"，则是",{text:"犯法",glossary:"fanfa"},"也，良田未得悟耳。"]],note:["如果只是被文字训诂束缚，那就是违背了易的活法——正是因为没有得到领悟。（**这是本书批评的最后一站**：从第一章「不知落处」到本章「束于辞训」，**麻衣批的始终是同一件事：把活的做成死的。** 原文「良田」当为「良由」之讹——「由」字上部未封口，被误写为「田」；「良由未得悟耳」意为「正是因为还没有得到领悟」。）"]},{id:"z41-05",label:"五、是为活法",showLabel:!0,sentences:[["果得悟焉，则",{text:"辞外见意",glossary:"ciwaiJianyi"},"，而纵横妙用，唯吾所欲，是为活法也。"]],note:["果真得到了领悟，就能在文字之外看见意义，纵横妙用、随心所欲——这就是活法。（**「纵横妙用，唯吾所欲」不是「随便乱用」**，而是**「随心所用而皆合于理」**——**就像一个真正的书法家，不再想着笔法规则，但每一笔都合于法度。规则内化了，所以忘记了规则，但处处都是规则。** 这就是本章「活法」的完整含义：**不是无法，是法已入心。**）"]},{id:"z41-06",label:"六、羲皇心地",showLabel:!0,sentences:[["故曰：“学《易》者当于羲皇心地上",{text:"驰骋",glossary:"chicheng"},"，无于周、孔言语下",{text:"拘挛",glossary:"juluan"},"。”"]],note:["所以说：「学《易》的人应当在伏羲的心灵境界上自由驰骋，不要在周文王、周公、孔子的文字语言下拘束蜷缩。」（**两个层次**：**羲皇心地**＝《易》的源头，无文字的直接感知；**周孔言语**＝《易》的传承，是工具而非目的。**与禅宗「以指指月，见月忘指」完全一致**：文字是手指，羲皇心地是月亮——**看见月亮之后，不要再盯着手指。**）"]}],o=[{id:"miman",term:"弥漫",pinyin:"mí màn",meaning:"充满、遍布。《易》道充满一切，无处不在。"},{id:"jiuliu",term:"九流",pinyin:"jiǔ liú",meaning:"先秦九大学派（儒、道、阴阳、法、名、墨、纵横、杂、农），泛指各种学问路径。"},{id:"huofa",term:"活法",pinyin:"huó fǎ",meaning:"活的方法、灵活的法则。对应「死法」（僵化的规则），是本章核心词。"},{id:"ziwu",term:"自悟",pinyin:"zì wù",meaning:"自己领悟。不能靠别人传授，必须自己体悟。"},{id:"shulei",term:"庶类",pinyin:"shù lèi",meaning:"众多事物、万类。文王周公从万事万物的变化来理解易。"},{id:"bawu",term:"八物",pinyin:"bā wù",meaning:"八卦所象之物。孔子以八物入，是「最精准的入法」。"},{id:"lüdu",term:"律度",pinyin:"lǜ dù",meaning:"音律与度量。以音律、度量衡的数理来入易。"},{id:"lishu",term:"历数",pinyin:"lì shù",meaning:"历法与数术。以天文历法来入易。"},{id:"xiandao",term:"仙道",pinyin:"xiān dào",meaning:"道教修炼之道。以内丹、修仙来入易。"},{id:"cixun",term:"辞训",pinyin:"cí xùn",meaning:"文字训诂。束于辞训即只在字词解释上打转，不得真义。"},{id:"fanfa",term:"犯法",pinyin:"fàn fǎ",meaning:"违犯法度。此处「法」指易的活法——束于辞训反而违背了易的精神。"},{id:"ciwaiJianyi",term:"辞外见意",pinyin:"cí wài jiàn yì",meaning:"在文字之外看见意义。第六章的核心命题，本章是它的最终落实（活法）。"},{id:"chicheng",term:"驰骋",pinyin:"chí chěng",meaning:"骑马奔驰。自由奔放，不受拘束。"},{id:"juluan",term:"拘挛",pinyin:"jū luán",meaning:"拘束、蜷缩。被文字束缚，无法自由。"}];return(b,n)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",20)),e(l,{colophon:"九流可入 · 当知活法 · 要须自悟 · 羲皇心地",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十一章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「良田未得悟耳」之「良田」当为「良由」之形讹（「由」字上部未封口而误作「田」），全句意为「正是因为还没有得到领悟」；此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"九流可入",pinyin:["jiǔ","liú"],meaning:"万物负阴而抱阳，任何学问都在阴阳之中——故任何领域都可以入《易》，《易》非一家的专属。"},{term:"活法与死法",pinyin:["huó","fǎ"],meaning:"死法：把文字当边界（束于辞训）；活法：把文字当窗口（辞外见意）。规则内化后忘了规则，才是活法。"},{term:"要须自悟",pinyin:["zì","wù"],meaning:"活法不能被教，只能被悟——因为「辞外」的东西无法用「辞」来传递。"},{term:"羲皇心地",pinyin:["xī","huáng"],meaning:"伏羲画卦时的那个状态：无文字，只对天地直接感知。是《易》的源头，也是最终的目的地。"},{term:"周孔言语",pinyin:["zhōu","kǒng"],meaning:"卦辞、爻辞、十翼。是《易》的传承，是「最好的路」——但路不是目的地。"}]}),n[3]||(n[3]=t("",26))])}}});export{y as __pageData,x as default};
